import{_ as i,l as n,o as e,c as l,v as t,p as s,x as o,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"信用评级机构","description":"","frontmatter":{"title":"信用评级机构","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/credit-rating-agencies.md","filePath":"econ/credit-rating-agencies.md","lastUpdated":1789023840000}'),p={name:"econ/credit-rating-agencies.md"};function h(A,a,B,m,_,u){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="信用评级机构" tabindex="-1">信用评级机构 <a class="header-anchor" href="#信用评级机构" aria-label="Permalink to &quot;信用评级机构&quot;">​</a></h1><div class="epigraph"><p>评级把信用质量压缩成可验证的字母，供契约与监管使用；发行方付费与评级购物，使这个压缩过程本身成为代理问题。</p><footer>—— 据 Boot, Milbourn and Schmeits, Journal of Finance 2006；Bolton, Freixas and Shapiro, Journal of Finance 2012；对照 Partnoy 对监管许可的讨论</footer></div><p><a href="/econ/relationship-lending">上一课</a>的软信息不可转卖。公开债需要标准化意见。本课缺口是评级机构：信息生产、监管许可、以及付费模式如何扭曲。不重写关系的跨期补贴，不把证券化结构提前展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>契约门槛、投资级资格、资本监管权重，都挂钩评级。机构出售的是可验证的公共信号，降低重复监测。缺口是激励：发行方付费时，发行人选择最宽松的机构（评级购物），机构为份额放松标准。Bolton–Freixas–Shapiro：竞争在购物环境下可以降低信息质量。Boot–Milbourn–Schmeits：评级还有协调功能——触发条款与滚动，使评级成为焦点，不仅仅是信息。</p><p><span class="marginnote">监管许可（regulatory license）：法规把评级写成准入，需求变成合规而不是信息。Partnoy 强调：此时评级更像法律地位，准确性的市场约束变弱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把评级写成契约的状态变量：降级触发加速、抵押加码、商业票据市场关闭——与短债展期同一扇门。信息角色：滞后、通过周期（through-the-cycle）使评级对周期不敏感，危机时突然跳。资本预算：依赖投资级资格的项目，APV 要含降级情景，不能只看承诺 \\(r_D\\)。</p><p>购物：结构复杂的证券（下一课 OTD）最容易选机构。企业债市场购物空间较小，但仍有。双评级要求减轻购物，不消除付费激励。</p>',9)),(e(),s(c,null,{default:o(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INFO%5B%22%E4%BF%A1%E6%81%AF%E5%8E%8B%E7%BC%A9%22%5D%20--%3E%20RATE%5B%22%E5%AD%97%E6%AF%8D%E8%AF%84%E7%BA%A7%22%5D%0A%20%20REG%5B%22%E7%9B%91%E7%AE%A1%E4%B8%8E%E5%A5%91%E7%BA%A6%E6%8C%82%E9%92%A9%22%5D%20--%3E%20LIC%5B%22%E8%AE%B8%E5%8F%AF%E9%9C%80%E6%B1%82%22%5D%0A%20%20PAY%5B%22%E5%8F%91%E8%A1%8C%E6%96%B9%E4%BB%98%E8%B4%B9%22%5D%20--%3E%20SHOP%5B%22%E8%AF%84%E7%BA%A7%E8%B4%AD%E7%89%A9%22%5D%0A%20%20SHOP%20--%3E%20QUAL%5B%22%E4%BF%A1%E6%81%AF%E8%B4%A8%E9%87%8F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20RATE%20--%3E%20TRIG%5B%22%E9%99%8D%E7%BA%A7%E8%A7%A6%E5%8F%91%E5%B1%95%E6%9C%9F%20%2F%20%E6%9D%A1%E6%AC%BE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 Miller 客户：投资级是免税机构与货币基金的准入门槛，需求在边界上不连续，企业愿意为保级牺牲税盾——动态权衡带被评级门槛切开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是公共信号的双重用途。作为信息，它应尽量准；作为契约焦点，它应稳定、少争议。通过周期是为契约稳定牺牲及时性。付费模式把卖方选成发行人，信号向发行人倾斜。危机中，焦点从稳定变成踩踏：集体降级触发条款，展期墙到来——He–Xiong 的到期风险被评级触发放大。</p><p>宏观课序的影子银行与批发融资已展示「合格资产」定义如何改变周期。本课企业侧：保级成为资本结构目标，有时压过 Leland 的税盾最优。</p><h3 id="不是「去掉评级就信息充分」" tabindex="-1">不是「去掉评级就信息充分」 <a class="header-anchor" href="#不是「去掉评级就信息充分」" aria-label="Permalink to &quot;不是「去掉评级就信息充分」&quot;">​</a></h3><p>分散债权人需要一个公共语言。问题是挂钩过紧与付费扭曲，不是字母本身。内部评级与市场信用利差是替代信号；利差更及时，但更噪、更循环——资本预算用哪一个，要看对象是契约触发还是期望损失。</p><p><span class="marginnote">Bolton, Freixas and Shapiro, <em>JF</em> 2012：购物加竞争可以降低信息质量。焦点功能见 Boot, Milbourn and Schmeits, <em>JF</em> 2006。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成三大机构的沿革。下一课证券化：结构化产品把评级购物做到极致，发起–分销切断监测。企业主体评级仍是本课对象的中心。</p><p>后课默认：评级是信息加契约焦点；付费与挂钩造成购物与悬崖。保级可以扭曲 \\(D^\\ast\\)。降级触发必须进展期情景。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>评级压缩信用质量，供契约与监管使用，也因此成为悬崖。</li><li>发行方付费加购物可降低信息质量；竞争未必改善。</li><li>通过周期稳定契约、牺牲及时性；资本预算要做降级情景。</li><li>出处：Boot, Milbourn and Schmeits, <em>JF</em> 2006；Bolton, Freixas and Shapiro, <em>JF</em> 2012。</li></ul>',12))])}const D=i(p,[["render",h]]);export{f as __pageData,D as default};
